import {escape,renderBlocks,categories} from '/cms-render.mjs';
import {publicCMSConfig} from '/cms-config.mjs';
const $=s=>document.querySelector(s),form=$('#post-form');
let config=publicCMSConfig,session,current,blocks=[],assets=[],posts=[],dirty=false,busy=false,refreshing;
const urls=new Map();
const msg=(text,error=false)=>{const el=$('#message');el.textContent=text;el.classList.toggle('cms-error',error);};
const sessionKey='giunchan-cms-session';
function remember(data){session={access_token:data.access_token,refresh_token:data.refresh_token,expires_at:data.expires_at||Math.floor(Date.now()/1000)+data.expires_in};sessionStorage.setItem(sessionKey,JSON.stringify(session));}
async function request(resource,options={},token=true){if(!config?.url||!config?.key)throw new Error('홈페이지 연결 정보를 확인해 주세요.');if(token)await refresh();const r=await fetch(config.url+resource,{...options,headers:{apikey:config.key,...(token&&session?{Authorization:'Bearer '+session.access_token}:{}),...options.headers}});if(!r.ok){if(r.status===401&&token){sessionStorage.removeItem(sessionKey);session=null;showLogin();}throw new Error(r.status===401?'로그인이 만료됐습니다. 다시 로그인해 주세요.':r.status===403?'접근 권한이 없습니다.':'요청에 실패했습니다. 입력 내용과 연결을 확인해 주세요.');}if(r.status===204)return null;return r;}
async function refresh(){if(!session)throw new Error('로그인해 주세요.');if(session.expires_at>Date.now()/1000+60)return;if(!refreshing)refreshing=(async()=>{const r=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})},false);remember(await r.json());})().finally(()=>refreshing=null);await refreshing;}
async function rows(resource,options){const r=await request('/rest/v1/'+resource,options);return r?await r.json():[];}
function showLogin(){$('#login-panel').hidden=false;$('#dashboard').hidden=true;$('#editor').hidden=true;$('#logout').hidden=true;}
async function enter(){const user=await(await request('/auth/v1/user')).json();const admins=await rows('content_admins?user_id=eq.'+user.id+'&select=user_id');if(!admins.length)throw new Error('이 계정에는 관리자 권한이 없습니다.');$('#login-panel').hidden=true;$('#logout').hidden=false;await showList();}
async function run(action){if(busy)return;busy=true;const controls=[...document.querySelectorAll('button,input[type=file]')];controls.forEach(b=>b.disabled=true);try{await action();}catch(e){msg(e.message,true);}finally{busy=false;controls.forEach(b=>b.disabled=false);}}
async function getImage(object){if(!object)return '';if(object.startsWith('/assets/'))return object;if(urls.has(object))return urls.get(object);const r=await request('/storage/v1/object/authenticated/content-assets/'+object.split('/').map(encodeURIComponent).join('/'));const url=URL.createObjectURL(await r.blob());urls.set(object,url);return url;}
async function showList(){dirty=false;$('#editor').hidden=true;$('#dashboard').hidden=false;posts=await rows('posts?select=*&order=updated_at.desc&limit=100&offset=0');$('#load-more').hidden=posts.length<100;await listCards();msg('');}
async function listCards(){const container=$('#post-list');container.replaceChildren();const selected=posts.filter(p=>(!$('#filter-category').value||p.category===$('#filter-category').value)&&(!$('#filter-status').value||p.status===$('#filter-status').value)&&p.title.includes($('#search').value));if(!selected.length){container.textContent='표시할 글이 없습니다.';return;}for(const p of selected){const card=document.createElement('article');card.className='cms-card';const image=p.thumbnail_path?await getImage(p.thumbnail_path):'';card.innerHTML=`${image?`<img src="${escape(image)}" alt="${escape(p.thumbnail_alt)}">`:'<div class="cms-no-image">GIUNCHAN</div>'}<div><span>${escape(categories[p.category])} · ${escape({draft:'초안',published:'게시됨',archived:'휴지통'}[p.status])}</span><h2>${escape(p.title)}</h2><p>${escape(p.summary)}</p><button type="button">수정하기</button></div>`;card.querySelector('button').onclick=()=>run(()=>edit(p));container.append(card);}}
function fields(){const fd=new FormData(form);return Object.fromEntries(fd.entries());}
function payload(status){const f=fields();return {title:f.title.trim(),slug:f.slug.trim(),category:f.category,summary:f.summary,author:f.author,thumbnail_path:current.thumbnail_path||null,thumbnail_alt:f.thumbnail_alt,published_at:f.published_at?new Date(f.published_at+'T00:00:00+09:00').toISOString():null,status,content:{blocks},seo_title:f.seo_title||null,seo_description:f.seo_description||null,tags:f.tags.split(',').map(t=>t.trim()).filter(Boolean),details:{...(current.details||{}),subtype:f.subtype,publisher:f.publisher,source_url:f.source_url,journal:f.journal,year:f.year,doi:f.doi,ever_published:current.details?.ever_published||status==='published',attachments:assets.filter(a=>a.kind==='pdf').map(a=>a.storage_path)}};}
async function save(status,quiet=false){if(!form.reportValidity())throw new Error('제목·글 주소·게시일을 확인해 주세요.');if(current.id&&current.slug!==fields().slug&&current.details?.ever_published)throw new Error('게시된 글의 주소는 유지해 주세요.');if(config.reservedSlugs?.includes(fields().slug)&&!(current.id&&current.slug===fields().slug&&config.migratedSlugs?.includes(current.slug)&&current.details?.migration?.slug===current.slug))throw new Error('기존 홈페이지 글과 주소가 겹칩니다. 다른 주소를 입력해 주세요.');const data=payload(status);if(current.details?.migration&&data.title!==current.title){const visit=n=>{if(n.tag==='h1')n.children=data.title.split(/(GMK®)/).filter(Boolean).map(t=>t==='GMK®'?{type:'element',tag:'span',attrs:{class:'no-break'},children:[{type:'text',text:'GMK'},{type:'element',tag:'sup',attrs:{class:'registered-mark'},children:[{type:'text',text:'®'}]}]}:{type:'text',text:t});for(const child of n.children||[])visit(child);};blocks.forEach(visit);}let result;if(current.id)result=await rows('posts?id=eq.'+current.id+'&updated_at=eq.'+encodeURIComponent(current.updated_at),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(data)});else result=await rows('posts',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(data)});if(!result.length)throw new Error('다른 창에서 글이 변경됐습니다. 목록에서 다시 열어 주세요.');current=result[0];dirty=false;$('#archive').hidden=false;form.elements.slug.readOnly=!!current.details?.ever_published;if(!quiet)msg(status==='published'?'게시했습니다. 홈페이지에서 확인해 주세요.':status==='archived'?'휴지통으로 이동했습니다.':'초안을 저장했습니다.');}
async function edit(post){form.reset();urls.forEach(u=>URL.revokeObjectURL(u));urls.clear();current=post?structuredClone(post):{status:'draft',thumbnail_path:null};blocks=structuredClone(post?.content?.blocks||[{type:'paragraph',text:''}]);assets=post?await rows('post_assets?post_id=eq.'+post.id):[];for(const key of ['title','slug','category','summary','author','thumbnail_alt','seo_title','seo_description'])if(post?.[key]!=null)form.elements[key].value=post[key];form.elements.published_at.required=!post?.details?.migration?.date_unknown;form.elements.published_at.value=post?.published_at?new Date(new Date(post.published_at).getTime()+9*3600000).toISOString().slice(0,10):post?.details?.migration?.date_unknown?'':new Date(Date.now()+9*3600000).toISOString().slice(0,10);form.elements.tags.value=(post?.tags||[]).join(', ');for(const [key,value] of Object.entries(post?.details||{}))if(form.elements[key])form.elements[key].value=value;form.elements.slug.readOnly=!!post?.details?.ever_published;$('#archive').hidden=!post;$('#dashboard').hidden=true;$('#editor').hidden=false;await cover();renderEditor();renderAttachments();dirty=false;msg('');}
async function cover(){const img=$('#cover-preview');img.hidden=!current.thumbnail_path;if(current.thumbnail_path)img.src=await getImage(current.thumbnail_path);else img.removeAttribute('src');}
function input(label,value,onChange,multiline=true){const wrap=document.createElement('label');wrap.textContent=label;const el=document.createElement(multiline?'textarea':'input');if(multiline)el.rows=4;el.value=value||'';el.oninput=()=>{onChange(el.value);dirty=true;};wrap.append(el);return wrap;}
function renderEditor(){const container=$('#blocks');container.replaceChildren();blocks.forEach((b,i)=>{const item=document.createElement('section');item.className='cms-block';const bar=document.createElement('div');bar.className='cms-block-tools';bar.textContent=`${i+1}. ${{element:'구조화 콘텐츠',text:'텍스트',paragraph:'문단',heading:'소제목',image:'이미지 (한 장 교체)',gallery:'이미지 모음',table:'표',link:'출처 링크',faq:'FAQ'}[b.type]||'블록'}`;for(const [label,action] of [['↑',()=>{if(i>0)[blocks[i-1],blocks[i]]=[blocks[i],blocks[i-1]];}],['↓',()=>{if(i<blocks.length-1)[blocks[i+1],blocks[i]]=[blocks[i],blocks[i+1]];}],['삭제',()=>blocks.splice(i,1)]]){const button=document.createElement('button');button.type='button';button.textContent=label;button.onclick=()=>{action();dirty=true;renderEditor();};bar.append(button);}item.append(bar);
 if(b.type==='element'||b.type==='text')item.append(editorialFields(b));
 if(['paragraph','heading'].includes(b.type))item.append(input(b.type==='heading'?'소제목':'문단',b.text,v=>b.text=v,b.type==='paragraph'));
 if(b.type==='table')item.append(input('한 줄에 한 행, 칸 사이는 탭 또는 | 로 구분하세요. 첫 행은 표 제목입니다.',b.rows?.map(r=>r.join(' | ')).join('\n'),v=>b.rows=v.split('\n').map(r=>r.split(/\t|\|/).map(c=>c.trim()))));
 if(b.type==='link'){item.append(input('링크 설명',b.text,v=>b.text=v,false),input('URL',b.url,v=>b.url=v,false));}
 if(b.type==='faq')item.append(input('질문',b.question,v=>b.question=v,false),input('답변',b.answer,v=>b.answer=v));
 if(b.type==='image'){const upload=document.createElement('input');upload.type='file';upload.accept='image/jpeg,image/png,image/webp,image/avif';upload.onchange=()=>run(async()=>{const a=await uploadAsset(upload.files[0],'image');b.path=a.storage_path;dirty=true;renderEditor();});item.append(upload,input('이미지 설명',b.alt,v=>b.alt=v,false),input('캡션',b.caption,v=>b.caption=v,false));if(b.path){const img=document.createElement('img');getImage(b.path).then(url=>img.src=url).catch(e=>msg(e.message,true));img.alt=b.alt||'';item.append(img);}}
 if(b.type==='gallery'){b.images ||= [];const help=document.createElement('p');help.textContent='최대 3장. 추가 업로드는 기존 사진 뒤에 이어집니다. PC 가로 배치 / 모바일 세로 배치';item.append(help);const upload=document.createElement('input');upload.type='file';upload.multiple=true;upload.accept='image/jpeg,image/png,image/webp,image/avif';upload.onchange=()=>run(async()=>{const files=Array.from(upload.files);if(b.images.length+files.length>3)throw new Error('이미지 모음에는 최대 3장을 넣을 수 있습니다.');if(!current.id)await save('draft',true);for(const file of files){const a=await uploadAsset(file,'image');b.images.push({path:a.storage_path,alt:'',caption:''});dirty=true;}renderEditor();});item.append(upload);b.images.forEach((photo,j)=>{const section=document.createElement('div');section.className='cms-gallery-edit';section.append(input(`사진 ${j+1} 설명`,photo.alt,v=>photo.alt=v,false),input('캡션',photo.caption,v=>photo.caption=v,false));const img=document.createElement('img');getImage(photo.path).then(url=>img.src=url).catch(e=>msg(e.message,true));img.alt=photo.alt||'';section.append(img);for(const [label,action] of [['←',()=>{if(j>0)[b.images[j-1],b.images[j]]=[b.images[j],b.images[j-1]];}],['→',()=>{if(j<b.images.length-1)[b.images[j+1],b.images[j]]=[b.images[j],b.images[j+1]];}],['사진 삭제',()=>b.images.splice(j,1)]]){const btn=document.createElement('button');btn.type='button';btn.textContent=label;btn.onclick=()=>{action();dirty=true;renderEditor();};section.append(btn);}item.append(section);});}
 container.append(item);});}
function editorialFields(node){const box=document.createElement('div');box.className='cms-structured-block';if(node.type==='text'){if(node.text.trim())box.append(input('본문',node.text,v=>node.text=v));return box;}const label=document.createElement('strong');label.textContent=({header:'글 머리말',p:'문단',h1:'제목',h2:'소제목',h3:'소제목 / FAQ',figure:'이미지와 캡션',nav:'목차',ol:'순서 목록',ul:'목록',li:'항목',table:'표',tr:'행',th:'제목 셀',td:'내용 셀',video:'영상 플레이어',source:'영상 파일',a:'링크',strong:'강조',sup:'윗첨자',figcaption:'캡션'}[node.tag]||node.tag);box.append(label);for(const key of ['src','href','alt','poster'])if(node.attrs?.[key]!=null)box.append(input({src:'파일 URL',href:'링크 URL',alt:'ALT',poster:'영상 포스터'}[key],node.attrs[key],v=>node.attrs[key]=v,false));if(node.tag==='img'){const img=document.createElement('img');img.src=node.attrs.src;img.alt=node.attrs.alt||'';box.append(img);}for(const child of node.children||[])box.append(editorialFields(child));return box;}
async function uploadAsset(file,kind){if(!file)return;if(file.size>20*1024*1024)throw new Error('파일은 20MB 이하로 올려 주세요.');if(kind==='pdf'?file.type!=='application/pdf':!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type))throw new Error('지원하지 않는 파일 형식입니다.');if(!current.id)await save('draft',true);const extension={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif','application/pdf':'pdf'}[file.type];const object=current.id+'/'+crypto.randomUUID()+'.'+extension;await request('/storage/v1/object/content-assets/'+object,{method:'POST',headers:{'Content-Type':file.type},body:file});const result=await rows('post_assets',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify({post_id:current.id,storage_path:object,original_name:file.name,kind})});assets.push(result[0]);msg('파일을 올렸습니다. 변경한 본문과 대표 이미지는 저장 또는 게시 버튼으로 반영해 주세요.');return result[0];}
function renderAttachments(){const ul=$('#attachments');ul.replaceChildren();for(const a of assets.filter(a=>a.kind==='pdf')){const li=document.createElement('li');li.textContent=a.original_name+' ';const button=document.createElement('button');button.type='button';button.textContent='첨부 제외';button.onclick=()=>run(async()=>{await rows('post_assets?id=eq.'+a.id,{method:'DELETE'});assets=assets.filter(item=>item.id!==a.id);renderAttachments();msg('첨부파일 연결을 해제했습니다.');});li.append(button);ul.append(li);}}
$('#login-form').onsubmit=e=>{e.preventDefault();run(async()=>{const r=await request('/auth/v1/token?grant_type=password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#email').value,password:$('#password').value})},false);remember(await r.json());$('#password').value='';await enter();});};
$('#logout').onclick=()=>run(async()=>{try{await request('/auth/v1/logout',{method:'POST'});}finally{session=null;sessionStorage.removeItem(sessionKey);urls.forEach(u=>URL.revokeObjectURL(u));urls.clear();showLogin();msg('로그아웃했습니다.');}});
$('#new-post').onclick=()=>run(()=>edit());$('#back').onclick=()=>{if(!dirty||confirm('저장하지 않은 변경이 있습니다. 목록으로 돌아갈까요?'))run(showList);};
$('#load-more').onclick=()=>run(async()=>{const next=await rows('posts?select=*&order=updated_at.desc&limit=100&offset='+posts.length);posts.push(...next);$('#load-more').hidden=next.length<100;await listCards();});
for(const selector of ['#filter-category','#filter-status','#search'])$(selector).oninput=()=>run(listCards);
form.oninput=()=>dirty=true;form.onsubmit=e=>{e.preventDefault();run(()=>save('published'));};$('#save-draft').onclick=()=>run(()=>save('draft'));$('#archive').onclick=()=>{if(confirm('이 글을 비공개로 전환하고 휴지통으로 옮길까요?'))run(()=>save('archived'));};
document.querySelectorAll('[data-add]').forEach(button=>button.onclick=()=>{blocks.push({type:button.dataset.add,text:''});dirty=true;renderEditor();});
$('#cover-upload').onchange=()=>run(async()=>{const a=await uploadAsset($('#cover-upload').files[0],'image');current.thumbnail_path=a.storage_path;dirty=true;await cover();});$('#remove-cover').onclick=()=>{current.thumbnail_path=null;dirty=true;cover();};$('#pdf-upload').onchange=()=>run(async()=>{await uploadAsset($('#pdf-upload').files[0],'pdf');renderAttachments();$('#pdf-upload').value='';});
$('#preview').onclick=()=>run(async()=>{if(!form.reportValidity())return;const p=payload(current.status);const body=$('#preview-body');body.innerHTML=`<h1>${escape(p.title)}</h1><p class="cms-summary">${escape(p.summary)}</p>${p.thumbnail_path?`<img class="cms-cover" src="${escape(await getImage(p.thumbnail_path))}" alt="${escape(p.thumbnail_alt)}">`:''}${renderBlocks(blocks)}`;for(const img of body.querySelectorAll('img')){const u=new URL(img.src);if(u.searchParams.has('path'))img.src=await getImage(u.searchParams.get('path'));}$('#preview-dialog').showModal();});$('#preview-close').onclick=()=>$('#preview-dialog').close();$('#preview-width').onchange=()=>$('#preview-body').style.maxWidth=$('#preview-width').value;
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
try{const r=await fetch('/api/content?action=config');if(r.ok){const loaded=await r.json();if(!loaded?.url||!loaded?.key)throw new Error('홈페이지 연결 정보가 올바르지 않습니다.');config=loaded;}else{const reserved=await fetch('/cms-reserved.json');if(!reserved.ok)throw new Error('홈페이지 연결 정보를 불러오지 못했습니다. 새로고침해 주세요.');config={...publicCMSConfig,reservedSlugs:await reserved.json()};}try{session=JSON.parse(sessionStorage.getItem(sessionKey));}catch{session=null;}if(session)await enter();}catch(e){showLogin();msg(e.message,true);}
